#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<long long> kthSmallestEven(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
        int n = nums.size();
        std::vector<int> prefEvens(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            prefEvens[i + 1] = prefEvens[i] + (nums[i] % 2 == 0 ? 1 : 0);
        }
        std::vector<long long> ans;
        for (const auto& q : queries) {
            int l = q[0], r = q[1];
            long long k = q[2];
            long long low = 2, high = 2LL * (k + n);
            long long res = -1;
            while (low <= high) {
                long long mid = (low + high) / 2;
                if (mid % 2 != 0) mid--;
                auto it = std::upper_bound(nums.begin(), nums.end(), (int)std::min<long long>(mid, 2e9));
                int pos = std::min<int>(r, (it - nums.begin()) - 1);
                int removed = (pos >= l) ? (prefEvens[pos + 1] - prefEvens[l]) : 0;
                long long remaining = (mid / 2) - removed;
                if (remaining >= k) {
                    res = mid;
                    high = mid - 2;
                } else {
                    low = mid + 2;
                }
            }
            ans.push_back(res);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long[] kthSmallestEven(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] prefEvens = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefEvens[i + 1] = prefEvens[i] + (nums[i] % 2 == 0 ? 1 : 0);
        }
        long[] ans = new long[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int l = queries[qi][0], r = queries[qi][1];
            long k = queries[qi][2];
            long low = 2, high = 2L * (k + n);
            long res = -1;
            while (low <= high) {
                long mid = (low + high) / 2;
                if (mid % 2 != 0) mid--;
                int idx = Arrays.binarySearch(nums, (int)Math.min(mid, (long)Integer.MAX_VALUE));
                if (idx < 0) idx = -idx - 2;
                int pos = Math.min(r, idx);
                int removed = (pos >= l) ? (prefEvens[pos + 1] - prefEvens[l]) : 0;
                long remaining = (mid / 2) - removed;
                if (remaining >= k) {
                    res = mid;
                    high = mid - 2;
                } else {
                    low = mid + 2;
                }
            }
            ans[qi] = res;
        }
        return ans;
    }
}

function kthSmallestEven(nums, queries) {
    const n = nums.length;
    const prefEvens = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefEvens[i + 1] = prefEvens[i] + (nums[i] % 2 === 0 ? 1 : 0);
    }

    function bisectRight(arr, target) {
        let low = 0, high = arr.length;
        while (low < high) {
            const mid = (low + high) >> 1;
            if (arr[mid] <= target) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    const ans = [];
    for (const [l, r, k] of queries) {
        let low = 2n, high = 2n * BigInt(k + n);
        let res = -1n;
        while (low <= high) {
            let mid = (low + high) / 2n;
            if (mid % 2n !== 0n) mid--;
            const pos = Math.min(r, bisectRight(nums, Number(mid)) - 1);
            const removed = (pos >= l) ? (prefEvens[pos + 1] - prefEvens[l]) : 0;
            const remaining = (mid / 2n) - BigInt(removed);
            if (remaining >= BigInt(k)) {
                res = mid;
                high = mid - 2n;
            } else {
                low = mid + 2n;
            }
        }
        ans.push(Number(res));
    }
    return ans;
}
